# qos-wire-decode：CONFIG 复用 link-flow-decode 的端口模式、协商、总字节
# 缓存（queue_bytes）、流控（flow_control）、老化与最大帧，顶层再加 qos
# （map/cap/mode/weights/drop，形状同 qos-decode）。事件仅接受原始帧、
# link、advance（service 一律非法）。帧合法性、VLAN 归属与转发判定沿用
# link-flow-decode；各出口副本按最终 802.1Q priority 经 map 入四个优先级
# 队列，同时受本队列字节限额（tail：cap；weighted：ceil(cap*w_i/sum w)）
# 与端口总字节限额 queue_bytes 约束，拒绝只影响该出口。发送器空闲（或
# advance 结算出现空闲点）时按 sp（最高非空队列）或 wrr（续用 qos-decode
# 权重轮次与队列顺序、跳过空队列）选取下一副本；发送不可抢占，时长按
# 协商速率、帧长与 20 字节线缆开销向上取整。链路降级、半双工冲突及
# PAUSE 对在发帧与等待队列的影响沿用 link-flow-decode；同一时刻先结算
# 到期项，末事件后不自动排空。
# ---------------------------------------------------------------------------

QOS_WIRE_CONFIG_KEYS = LINK_WIRE_CONFIG_KEYS | frozenset(("qos",))


def validate_qos_wire_config(config):
    """qos-wire-decode 配置：link-flow-decode 五键加 qos 子文档。"""
    if (
        not isinstance(config, dict)
        or frozenset(config) != QOS_WIRE_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    # ports/age/max_frame/delay（含 rates/modes/queue_bytes/flow_control）
    # 全量校验同 link-flow-decode
    fwd_ports, caps, queues, flows, age, max_frame, delay = (
        validate_link_flow_config(
            {key: config[key] for key in LINK_WIRE_CONFIG_KEYS}
        )
    )
    qos_doc = config["qos"]
    if not isinstance(qos_doc, dict) or frozenset(qos_doc) != QOS_KEYS:
        raise InvalidInput("bad qos")
    mapping = qos_doc["map"]
    cap = qos_doc["cap"]
    mode = qos_doc["mode"]
    weights = qos_doc["weights"]
    drop = qos_doc["drop"]
    if (
        not isinstance(mapping, list)
        or len(mapping) != 8
        or not all(_is_int(q) and 0 <= q <= 3 for q in mapping)
    ):
        raise InvalidInput("bad qos map")
    if not _is_int(cap) or cap <= 0:
        raise InvalidInput("bad qos cap")
    if mode not in QOS_SCHED_MODES:
        raise InvalidInput("bad qos mode")
    if (
        not isinstance(weights, list)
        or len(weights) != 4
        or not all(_is_int(w) and w > 0 for w in weights)
    ):
        raise InvalidInput("bad qos weights")
    if drop not in QOS_DROP_MODES:
        raise InvalidInput("bad qos drop")
    qos = {
        "map": list(mapping),
        "cap": cap,
        "mode": mode,
        "weights": list(weights),
        "drop": drop,
    }
    return fwd_ports, caps, queues, flows, qos, age, max_frame, delay


def validate_qos_wire_events(events, fwd_ports):
    """qos-wire-decode 事件：link/advance/{t,port,data}，service 非法。

    全量校验口径同 link-flow-decode（PAUSE 合法性是运行期结果而非输入
    错误），仅在事件形状层面拒绝 service 及其余未知形状。
    """
    if not isinstance(events, list):
        raise InvalidInput("events must be a list")
    for event in events:
        if not isinstance(event, dict):
            raise InvalidInput("bad event")
        keys = frozenset(event)
        if keys not in (
            FRAME_DECODE_FRAME_KEYS,
            LINK_WIRE_LINK_EVENT_KEYS,
            LINK_WIRE_ADVANCE_EVENT_KEYS,
        ):  # service 等其他形状一律非法输入
            raise InvalidInput("bad event")
    return validate_link_flow_decode_events(events, fwd_ports)


def _qos_wire_priority(raw):
    """单层 802.1Q 标签帧取 TCI 高 3 位优先级；未标记帧优先级为 0。"""
    if raw[12:14] == FRAME_DECODE_TAG:
        return ((raw[14] << 8) | raw[15]) >> 13
    return 0


def _decode_qos_wire_events(events):
    """校验后的 qos-wire 事件对：link/advance 原样；frame 附解码九元组。

    口径同 _decode_link_flow_events（frame-decode 解码，alignment 恒真）；
    工作量预演与正式仿真共用同一纯函数转换。
    """
    raw_frames = [
        (item[1], item[2], item[3]) for item in events if item[0] == "frame"
    ]
    decoded_frames = _decode_raw_frames(raw_frames)
    decoded = []
    frame_index = 0
    for item in events:
        if item[0] == "frame":
            decoded.append(
                ("frame", item[1], item[2], item[3],
                 decoded_frames[frame_index])
            )
            frame_index += 1
        else:
            decoded.append(item)
    return decoded


def qos_wire(
    fwd_ports, caps, queues, flows, qos, age, max_frame, delay, events,
    work_limit=None, observer=None,
):
    """qos-wire-decode 仿真：四优先级队列在线速链路上确定性发送。

    在 link-flow-decode 线速/协商/半双工/PAUSE 模型上，把每口单一等待
    序列改为四个优先级 FIFO（帧与字节双计，含正在发送的队头副本），受
    端口总字节限额与每队列字节限额约束；发送器空闲（含 advance 结算产生
    的空闲点）时按 sp（最高非空队列）或 wrr（续用 qos-decode 权重轮次与
    队列顺序、跳过空队列）选取下一副本。发送非抢占，链路降级/冲突/PAUSE
    语义沿用 link-flow-decode。work_limit 非 None 时按计费点累计 W（初值
    P），首次超过即抛 QosWireWorkLimit；预演与正式仿真共用本函数。
    """
    order = {port["name"]: i for i, port in enumerate(fwd_ports)}
    by_name = {port["name"]: port for port in fwd_ports}
    qos_map = qos["map"]
    cap = qos["cap"]
    sched_mode = qos["mode"]
    weights = qos["weights"]
    drop_mode = qos["drop"]
    weight_total = sum(weights)
    # 每队列字节限额：tail 即四队列共用 cap；weighted 按权重上取整
    queue_limits = [-(-(cap * w) // weight_total) for w in weights]
    committed = {name: ("down",) for name in by_name}
    pending = {}  # name -> (rate, mode, deadline)
    fdb = {}  # (vlan, mac) -> [port, seen]
    # 每口四队列等待副本（未开始）；head 为正在发送副本（None 发送器空闲）
    waitq = {
        name: [deque(), deque(), deque(), deque()] for name in by_name
    }
    head = {name: None for name in by_name}
    # 各队列剩余帧/字节（等待副本与队头副本均计入，离开端口时核减）
    qframes = {name: [0, 0, 0, 0] for name in by_name}
    qbytes = {name: [0, 0, 0, 0] for name in by_name}
    txq = {name: [0, 0, 0, 0] for name in by_name}
    dropq = {name: [0, 0, 0, 0] for name in by_name}
    occupied = {name: 0 for name in by_name}  # 四队列字节总和
    # 每口持久 WRR 状态 (当前队, 剩余配额)，初始服务 3 队，同 qos-decode
    wrr_state = {name: [3, weights[3]] for name in by_name}
    # PAUSE：pause_until 为发送截止时刻（None 未暂停）；hold_began 为队头
    # 完成后因暂停无法开始的等待区间起点；pause_ns 为累计实际暂停时长
    pause_until = {name: None for name in by_name}
    hold_began = {name: None for name in by_name}
    pause_ns = {name: 0 for name in by_name}
    stats = {
        name: {
            "rx_frames": 0,
            "rx_bytes": 0,
            "tx_frames": 0,
            "tx_bytes": 0,
            "collision_frames": 0,
            "collision_bytes": 0,
            "queue_full_frames": 0,
            "queue_full_bytes": 0,
            "quota_full_frames": 0,
            "quota_full_bytes": 0,
            "link_down_frames": 0,
            "link_down_bytes": 0,
            "pause_frames": 0,
            "pause_unsupported_frames": 0,
            "pause_duration_ns": 0,
        }
        for name in by_name
    }
    results = []
    if observer is not None:
        observer["items"] = []
    work = len(fwd_ports)  # W 初值 P
    if work_limit is not None and work > work_limit:
        raise QosWireWorkLimit()

    def charge(n=1):
        nonlocal work
        work += n
        if work_limit is not None and work > work_limit:
            raise QosWireWorkLimit()

    def is_up(name):
        return name not in pending and committed[name][0] == "up"

    def accrue_hold(name, now):
        # 口径同 link-flow-decode：按墙钟累计暂停实际生效区间
        began = hold_began[name]
        until = pause_until[name]
        if until is not None and now >= until:
            if began is not None and until > began:
                pause_ns[name] += until - began
            hold_began[name] = None
            pause_until[name] = None
            return
        if began is None or now <= began:
            return
        pause_ns[name] += now - began
        hold_began[name] = now if until is not None else None

    def settle_negotiations(t):
        settled = 0
        for port in fwd_ports:
            name = port["name"]
            if name in pending and pending[name][2] <= t:
                rate, mode, _ = pending.pop(name)
                committed[name] = ("up", rate, mode)
                settled += 1
        return settled

    def pick_waiting(name, now):
        """发送器空闲时选择下一副本并置为队头；无等待副本返回 False。

        sp：取编号最高的非空队列；wrr：续用持久 (q, rem)，跳过空队列，
        每发一帧 rem 减 1，rem 用尽或当前队变空时推进（队列顺序
        3→2→1→0）并重置配额。开始时刻不早于副本锚点与暂停截止时刻。
        """
        if sched_mode == "sp":
            q = next((q for q in (3, 2, 1, 0) if waitq[name][q]), None)
            if q is None:
                return False
            copy = waitq[name][q].popleft()
        else:
            q, rem = wrr_state[name]
            if not any(waitq[name][q0] for q0 in range(4)):

    """qos-wire-decode 工作量预演：独立状态跑同一仿真，无副作用、不产出。

    与 qos_wire 同一计费公式（W 初值 P，每输入事件、每条 results 记录、
    碰撞/PAUSE 后每个实际后移副本各计 1），等于上限合法，首次超过即抛
    QosWireWorkLimit。
    """
    qos_wire(
        fwd_ports, caps, queues, flows, qos, age, max_frame, delay, events,
        work_limit=limit,
    )


# ---------------------------------------------------------------------------
# qos-pfc-decode：在 qos-wire-decode（四队列、SP/WRR、802.3x 全局 PAUSE）
# 之上新增 802.1Qbb 优先级流控。CONFIG 每口再加 pfc：严格递增的 0..7 子序
# （空数组表示该口不支持 PFC）。事件仍仅 link/advance/原始帧。除全局 PAUSE
# 外，未标记、目的 01:80:c2:00:00:01、以太类型 0x8808、操作码 0x0101、恰
# 64 字节的好帧按 PFC 处理：两字节 class-enable 后按优先级 0..7 排八个两
# 字节 quanta，其余字节全零，否则 malformed_pfc（计时器不变）。链路须 up
# 且全双工，且 enable 置位的全部优先级均在入端口 pfc 允许集合内，否则
# pfc_unsupported 且任何项都不生效。置位项非零 quanta 把该优先级截止时刻
# 设为 t+ceil(quanta*512000/rate)，零值清除，未置位项保持不变。PFC 帧不
# 学习、转发或入队。数据帧仍按 qos.map 入四队列；队列暂停到全局 PAUSE 与
# “映射到该队列且在允许集合内”的有效 PFC 截止时刻的最大值。pfc_duration
# 仅累计各优先级实际阻塞其映射队列的显式时钟区间。其余语义（坏帧分类、
# 半双工碰撞、协商、SP/WRR、不自动排空）同 qos-wire-decode。
# ---------------------------------------------------------------------------

QOS_PFC_OPCODE = 0x0101


def validate_qos_pfc_config(config):
    """qos-pfc-decode 配置：qos-wire-decode 每口再加 pfc 字段。"""
    if (
        not isinstance(config, dict)
        or frozenset(config) != QOS_WIRE_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    ports_doc = config["ports"]
    if not isinstance(ports_doc, list) or not ports_doc:
        raise InvalidInput("ports must be a non-empty list")
    pfc_by_name = {}
    stripped_ports = []
    for port in ports_doc:
        if not isinstance(port, dict) or "pfc" not in port:
            raise InvalidInput("bad port")
        name = port.get("name")
        pfc = port["pfc"]
        # pfc：列表，元素为 0..7 整数，严格递增（空数组表示不支持）
        if (
            not isinstance(pfc, list)
            or not all(_is_int(p) and 0 <= p <= 7 for p in pfc)
            or any(pfc[i] >= pfc[i + 1] for i in range(len(pfc) - 1))
        ):
            raise InvalidInput("bad pfc")
        if isinstance(name, str):
            pfc_by_name[name] = frozenset(pfc)
        rest = {key: value for key, value in port.items() if key != "pfc"}
        stripped_ports.append(rest)
    # ports/age/max_frame/delay（含 rates/modes/queue_bytes/flow_control）与
    # qos 子文档全量校验同 qos-wire-decode（剥去每口 pfc 键后逐字复用）
    stripped = dict(config)
    stripped["ports"] = stripped_ports
    fwd_ports, caps, queues, flows, qos, age, max_frame, delay = (
        validate_qos_wire_config(stripped)
    )
    pfc_allowed = {port["name"]: pfc_by_name[port["name"]] for port in fwd_ports}
    return (
        fwd_ports, caps, queues, flows, qos, pfc_allowed, age, max_frame,
        delay,
    )


def validate_qos_pfc_events(events, fwd_ports):
    """qos-pfc-decode 事件：形状同 qos-wire-decode（PFC 合法性是运行期
    结果而非输入错误）。"""
    return validate_qos_wire_events(events, fwd_ports)


def _decode_qos_pfc_events(events):
    """校验后的 qos-pfc 事件对：与 qos-wire 同一纯函数解码。"""
    return _decode_qos_wire_events(events)


def qos_pfc(
    fwd_ports, caps, queues, flows, qos, pfc_allowed, age, max_frame, delay,
    events, work_limit=None, observer=None,
):
    """qos-pfc-decode 仿真：qos-wire 四队列模型加 802.1Qbb 逐优先级门控。

    work_limit 非 None 时按计费点累计 W（初值 P），首次超过即抛
    QosPfcWorkLimit；预演与正式仿真共用本函数。
    """
    order = {port["name"]: i for i, port in enumerate(fwd_ports)}
    by_name = {port["name"]: port for port in fwd_ports}
    qos_map = qos["map"]
    cap = qos["cap"]
    sched_mode = qos["mode"]
    weights = qos["weights"]
    drop_mode = qos["drop"]
    weight_total = sum(weights)
    queue_limits = [-(-(cap * w) // weight_total) for w in weights]
    # qi -> 映射到该队列的 802.1Q 优先级集合
    queue_prios = [frozenset(p for p in range(8) if qos_map[p] == qi)
                   for qi in range(4)]
    committed = {name: ("down",) for name in by_name}
    pending = {}
    fdb = {}
    waitq = {
        name: [deque(), deque(), deque(), deque()] for name in by_name
    }
    head = {name: None for name in by_name}
    qframes = {name: [0, 0, 0, 0] for name in by_name}
    qbytes = {name: [0, 0, 0, 0] for name in by_name}
    txq = {name: [0, 0, 0, 0] for name in by_name}
    dropq = {name: [0, 0, 0, 0] for name in by_name}
    occupied = {name: 0 for name in by_name}
    wrr_state = {name: [3, weights[3]] for name in by_name}
    # 全局 PAUSE（802.3x）：墙钟区间模型与 qos-wire-decode 逐字一致。
    pause_until = {name: None for name in by_name}
    hold_began = {name: None for name in by_name}
    pause_ns = {name: 0 for name in by_name}
    # PFC 截止时刻仅用于门控；各优先级实际阻塞时长在末态由 gate_log（门控
    # 状态变更点）与实际发送区间离线扫描：显式门控区间减去在发不抢占帧的
    # 占用区间，避免跨事件区间边界误差。
    pfc_until = {name: [None] * 8 for name in by_name}
    gate_log = {name: [(0, None, (None,) * 8)] for name in by_name}
    # 每次有效非零 PFC 置位记录 (到达时刻, 在发帧完成基准, 截止时刻)，供
    # 末态扫描把“在发不抢占帧占用”锚到该优先级自身的激活点。
    pfc_activations = {name: [] for name in by_name}
    pfc_ns = {name: [0] * 8 for name in by_name}
    stats = {
        name: {
            "rx_frames": 0,
            "rx_bytes": 0,
            "tx_frames": 0,
            "tx_bytes": 0,
            "collision_frames": 0,
            "collision_bytes": 0,
            "queue_full_frames": 0,
            "queue_full_bytes": 0,
            "quota_full_frames": 0,
            "quota_full_bytes": 0,
            "link_down_frames": 0,
            "link_down_bytes": 0,
            "pause_frames": 0,
            "pause_unsupported_frames": 0,
            "pause_duration_ns": 0,
            "pfc_frames": 0,
            "pfc_unsupported_frames": 0,
            "pfc_duration_ns": [0] * 8,
        }
        for name in by_name
    }
    results = []
    if observer is not None:
        observer["items"] = []
    work = len(fwd_ports)
    if work_limit is not None and work > work_limit:
        raise QosPfcWorkLimit()

    def charge(n=1):
        nonlocal work
        work += n
        if work_limit is not None and work > work_limit:
            raise QosPfcWorkLimit()

    def is_up(name):
        return name not in pending and committed[name][0] == "up"

    def queue_gate(name, qi, now):
        """队列 qi 在 now 的暂停截止：全局 PAUSE 与有效 PFC 最大值。

        有效 PFC 截止仅计入映射到 qi 且在该口 pfc 允许集合内的优先级；
        已到期（<= now）的截止视为 None。
        """
        gate = pause_until[name]
        if gate is not None and gate <= now:
            gate = None
        allowed = pfc_allowed[name]

    # （applied）才加 1（同时刻同口幂等重复学习不计），安全模式每次
    # reload/rollback（无变化亦算）加 1，stp/环路模式链路 up 实际改变
    # （applied）才加 1，链路协商
    # 模式仅 applied 链路项加 1（帧项恒 applied 但不计），链路状态模式
    # 仅 applied 项加 1，qos/lag/mirror/acl/security-check/qos-check/
    # qos-decode/acl-check/mirror-check/lag-check/storm-check 模式仅
    # applied 链路/成员项加 1（帧与 service 恒 applied 但不计），forward-stp/stp-decode/
    # stp-check/forward-stp-storm 模式仅 applied 链路项加 1（帧项恒
    # applied 但不计），forward-static 模式帧恒 applied 且 version 恒 0
    version = 0
    for event, observed in zip(events, items):
        kind = _event_kind(event)
        if kind != observed["kind"]:
            raise InvalidInput("bad log")
        if mode in ("fdb", "stp", "loop"):
            if observed["applied"]:
                version += 1
        elif mode in (
            "link_forward", "link_wire", "link_wire_decode",
            "link_flow_decode", "forward_stp",
            "stp_decode", "stp_check", "forward_stp_storm"
        ):
            if kind == "link" and observed["applied"]:
                version += 1
        elif mode == "link_state":
            if observed["applied"]:
                version += 1
        elif mode in (
            "qos", "lag", "mirror", "acl", "security_check", "qos_check",
            "qos_decode",
            "acl_check", "mirror_check", "lag_check", "storm_check"
        ):
            if kind in ("link", "member") and observed["applied"]:
                version += 1
        elif kind in ("reload", "rollback"):
            version += 1
        records.append(
            {
                "t": event["t"],
                "version": version,
                "event": _canonical(event),
                "applied": observed["applied"],
                "output": observed["output"],
            }
        )
    doc = {
        "schema": RECORD_SCHEMA,
        "config": _canonical(config),
        "records": records,
    }
    doc["sha256"] = hashlib.sha256(_log_prefix_bytes(doc)).hexdigest()
    return doc


def _log_prefix_bytes(doc):
    """sha256 摘要文本：schema,config,records 规范序列化后含 LF。"""
    prefix = {
        "schema": doc["schema"],
        "config": doc["config"],
        "records": doc["records"],
    }
    return (
        json.dumps(prefix, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _log_bytes(doc):
    ordered = {key: doc[key] for key in LOG_KEYS}
    return (
        json.dumps(ordered, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _assert_canonical_order(value):
    """config/event 内对象键须递归按 Unicode 码点升序，数组保序。"""
    if isinstance(value, dict):
        keys = list(value)
        if keys != sorted(keys):
            raise InvalidInput("bad log key order")
        for item in value.values():
            _assert_canonical_order(item)
    elif isinstance(value, list):
        for item in value:
            _assert_canonical_order(item)


def _json_equal(a, b):
    """JSON 值深比较；bool 不与 int 混同，键序无关，数组保序。"""
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(
            _json_equal(a[key], b[key]) for key in a
        )
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(
            _json_equal(x, y) for x, y in zip(a, b)
        )
    if a is None or b is None:
        return a is None and b is None
    return type(a) is type(b) and a == b


def _validate_log_shape(log):
    """严格校验 LOG 字段、类型、键序；不含语义重放。"""
    if not isinstance(log, dict) or list(log) != list(LOG_KEYS):
        raise InvalidInput("bad log")
    if not _is_int(log["schema"]) or log["schema"] != RECORD_SCHEMA:
        raise InvalidInput("bad log schema")
    config = log["config"]
    if not isinstance(config, dict):
        raise InvalidInput("bad log config")
    _assert_canonical_order(config)
    records = log["records"]
    if not isinstance(records, list):
        raise InvalidInput("bad log records")
    for record in records:
        if not isinstance(record, dict) or list(record) != list(RECORD_KEYS):
            raise InvalidInput("bad log record")
        if not _is_int(record["t"]) or record["t"] < 0:
            raise InvalidInput("bad log t")
        if not _is_int(record["version"]) or record["version"] < 0:
            raise InvalidInput("bad log version")
        event = record["event"]
        if not isinstance(event, dict):
            raise InvalidInput("bad log event")
        _assert_canonical_order(event)
        _event_kind(event)
        if not isinstance(record["applied"], bool):
            raise InvalidInput("bad log applied")
        # output 通常为对象或 null；link-wire 模式下为结果对象数组（可为
        # 空数组）。语义重放再逐项核对其精确值。
        if record["output"] is not None and not isinstance(
            record["output"], (dict, list)
        ):
            raise InvalidInput("bad log output")
    digest = log["sha256"]
    if not isinstance(digest, str) or _HEX64_RE.fullmatch(digest) is None:
        raise InvalidInput("bad log sha256")


def _verify_records(log, events, items):
    """重放后逐项核对 t/version/event/applied/output。"""
    records = log["records"]
    if len(records) != len(items):
        raise InvalidInput("bad log records")
    mode = _log_mode(log["config"], events)
    version = 0
    for event, observed, record in zip(events, items, records):
        kind = _event_kind(event)
        if kind != observed["kind"]:
            raise InvalidInput("bad log record")
        if mode in ("fdb", "stp", "loop"):
            if observed["applied"]:
                version += 1
        elif mode in (
            "link_forward", "link_wire", "link_wire_decode",
            "link_flow_decode", "forward_stp",
            "stp_decode", "stp_check", "forward_stp_storm"
        ):
            if kind == "link" and observed["applied"]:
                version += 1
        elif mode == "link_state":
            if observed["applied"]:
                version += 1
        elif mode in (
            "qos", "lag", "mirror", "acl", "security_check", "qos_check",
            "qos_decode",
            "acl_check", "mirror_check", "lag_check", "storm_check"
        ):
            if kind in ("link", "member") and observed["applied"]:
                version += 1
        elif kind in ("reload", "rollback"):
            version += 1
        if record["t"] != event["t"]:
            raise InvalidInput("bad log t")
        if record["version"] != version:
            raise InvalidInput("bad log version")
        if not _json_equal(record["event"], _canonical(event)):
            raise InvalidInput("bad log event")
        if record["applied"] is not observed["applied"]:
            raise InvalidInput("bad log applied")
        if not _json_equal(record["output"], observed["output"]):
            raise InvalidInput("bad log output")


def _atomic_write(path, payload):
    """同目录临时文件 + os.replace 原子写入；失败不改动目标。"""
    directory = os.path.dirname(os.path.abspath(path))
    fd, tmp_path = tempfile.mkstemp(prefix=".switch-log-", dir=directory)
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp_path, path)
    except OSError:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise


def _result_bytes(result):
    """stdout 载荷：紧凑 UTF-8 JSON 加一个 LF。"""
    return (
        json.dumps(result, ensure_ascii=False, separators=(",", ":")).encode(
            "utf-8"
        )
        + b"\n"
    )


